// Normalize authors to arrays everywhere.
// Accepts bracketed ("[A, B, C]"), bare comma-separated ("A, B, C"),
// or already-array forms. A single name with no comma stays a single author.
function normalizeAuthorsList(data) {
  data.forEach(pub => {
    if (Array.isArray(pub.authors)) {
      pub.authors = pub.authors.map(a => String(a).trim()).filter(Boolean);
    } else if (typeof pub.authors === 'string') {
      let raw = pub.authors.trim();
      if (raw === '' || raw === '[]') {
        pub.authors = [];
      } else {
        if (raw.startsWith('[') && raw.endsWith(']')) {
          raw = raw.slice(1, -1);
        }
        pub.authors = raw.split(',').map(s => s.trim()).filter(Boolean);
      }
    } else if (pub.authors == null) {
      pub.authors = [];
    }
  });
  return data;
}

const NORMALIZED_PUBLICATIONS_DATA = normalizeAuthorsList(PUBLICATIONS_DATA);

// Make sure PUBLICATIONS_DATA is available in global scope
window.PUBLICATIONS_DATA = NORMALIZED_PUBLICATIONS_DATA;
